answer:
function order(dish) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (dish === "うなぎ") reject(new Error("売り切れです"));
      else resolve(dish + "ができました");
    }, 300);
  });
}

async function safeOrder(dish) {
  try {
    return await order(dish);
  } catch (error) {
    return "注文できませんでした: " + error.message;
  }
}

console.log(await safeOrder("カレー"));
console.log(await safeOrder("うなぎ"));
